// Cloudflare Pages Function: Markdown for agents on the landing page.
//
// A request for / or /en/ with `Accept: text/markdown` gets the Markdown
// version of that page (site/index.md, site/en/index.md, generated by
// scripts/build-site.py) instead of the HTML. Browsers get the HTML as before.
//
// The app used to be called AgentDeck, at agentdeck.cassianflorin.com. That
// host is still attached to the project, and every request to it gets a 301
// to the same path on waitlight.cassianflorin.com, so old links and search
// results carry over. That is why site/_routes.json sends every path here;
// on the new host, anything but / and /en/ goes straight to the static file.

const OLD_HOST = "agentdeck.cassianflorin.com";
const NEW_HOST = "waitlight.cassianflorin.com";

const PAGES = {
  "/": { md: "/index.md", other: "/en/", otherLang: "en" },
  "/en/": { md: "/en/index.md", other: "/", otherLang: "zh-Hans" },
};

function linkHeader(page) {
  return [
    `</llms.txt>; rel="describedby"; type="text/plain"`,
    `</sitemap.xml>; rel="sitemap"; type="application/xml"`,
    `<${page.other}>; rel="alternate"; hreflang="${page.otherLang}"`,
    `<${page.md}>; rel="alternate"; type="text/markdown"`,
  ].join(", ");
}

// Rough token count for the x-markdown-tokens hint: CJK characters count about
// one token each, other text about four characters per token.
function estimateTokens(text) {
  const cjk = (text.match(/[　-鿿＀-￯]/g) || []).length;
  return cjk + Math.ceil((text.length - cjk) / 4);
}

function wantsMarkdown(request) {
  const accept = request.headers.get("Accept") || "";
  return /(^|[\s,])text\/markdown\b/i.test(accept);
}

export async function onRequest({ request, next, env }) {
  const url = new URL(request.url);
  if (url.hostname === OLD_HOST) {
    url.hostname = NEW_HOST;
    return Response.redirect(url.toString(), 301);
  }
  const page = PAGES[url.pathname];
  if (!page) return next();

  let response;
  if (wantsMarkdown(request) && (request.method === "GET" || request.method === "HEAD")) {
    const asset = await env.ASSETS.fetch(new URL(page.md, url));
    if (asset.ok) {
      const text = await asset.text();
      response = new Response(request.method === "HEAD" ? null : text, {
        headers: {
          "Content-Type": "text/markdown; charset=utf-8",
          "Cache-Control": "public, max-age=0, must-revalidate",
          "x-markdown-tokens": String(estimateTokens(text)),
        },
      });
    }
  }
  if (!response) {
    const html = await next();
    response = new Response(html.body, html);
  }

  // The same URL answers with HTML or Markdown, so caches must key on Accept.
  response.headers.append("Vary", "Accept");
  if (!response.headers.has("Link")) response.headers.set("Link", linkHeader(page));
  return response;
}
